<template>
  <div class="ct-form back-white">

    <div class="ct-field">
      <label class="ct-label">{{ $t('note_color') }}</label>
      <q-input
        dense
        outlined
        readonly
        class="input-sm"
        v-model="user_settings['ORG_COLOR_PREFERENCE']"
        :rules="['anyColor']"
      >
        <template v-slot:append>
          <q-icon name="colorize" class="cursor-pointer">
            <q-popup-proxy
              cover
              transition-show="scale"
              transition-hide="scale"
            >
              <q-color v-model="user_settings['ORG_COLOR_PREFERENCE']" />
            </q-popup-proxy>
          </q-icon>
        </template>
      </q-input>
    </div>

    <!-- Actions -->
    <div class="ct-footer">
      <q-btn
        unelevated
        :label="$t('reset')"
        color="negative"
        @click="resetTheme()"
        size="md"
        class="q-mr-sm"
      />
      <q-btn
        unelevated
        :label="$t('save')"
        color="primary"
        @click="saveTheme()"
        size="md"
      />
    </div>
  </div>
  <Loader />
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import Loader from 'src/components/Loader.vue';
import { useSettingStore } from 'src/store/main';
import helperMixin from 'src/mixins/helperMixin.js';
import { ApiExceptions } from 'src/exceptions/index';
export default defineComponent({
  el: '#app',
  mixins: [helperMixin],
  components: {
    Loader,
  },
  data() {
    return {
      origins: ref([]),
      userDialog: ref(false),
      api_key: '',
    };
  },
  methods: {
    resetTheme() {
      this.user_settings['ORG_COLOR_PREFERENCE'] = '#2388AE';
      this.saveTheme();
    },
    async saveTheme() {
      try {
        this.showLoading();

        await this.updateSetting(
          'ORG_COLOR_PREFERENCE',
          this.user_settings['ORG_COLOR_PREFERENCE'],
        );
        this.setOrgColor();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
  },
  setup() {
    const settings_store = useSettingStore();
    const { user_settings, loading_settings } = storeToRefs(settings_store);
    const { updateSetting, setOrgColor } = settings_store;

    return {
      user_settings,
      updateSetting,
      setOrgColor,
      loading_settings,

      theme_info: ref({
        banner_color: '',
        banner_text_color: '',
      }),
    };
  },
});
</script>

