<template>
  <div class="rc-form back-white" data-test="release-channel-card">
    <p class="rc-desc">{{ $t('release_channel_intro') }}</p>

    <!--
      Live proof of the per-org channel router (Multi-Org SD §9.3 B-4): the
      api /health is fetched THROUGH the router (DOC2API_URL on dev), so the
      version shown is the one THIS org actually runs on given its channel —
      an org on `latest` sees a higher version than one on `frozen`.
    -->
    <div
      v-if="api_version"
      class="rc-version-banner"
      data-test="release-channel-current-version"
    >
      <q-icon name="mdi-server-network" size="18px" class="q-mr-sm" />
      <span>{{ $t('release_channel_current_version') }}</span>
      <span class="rc-version-value">v{{ api_version }}</span>
      <q-badge
        v-if="api_channel"
        :color="api_channel === 'latest' ? 'primary' : 'grey-7'"
        :label="api_channel"
        class="q-ml-sm rc-version-channel"
        data-test="release-channel-current-channel"
      />
    </div>

    <div class="rc-options column q-gutter-md">
      <div class="rc-option">
        <q-radio
          dense
          v-model="selected_channel"
          val="latest"
          :label="$t('release_channel_latest_label')"
          data-test="release-channel-option-latest"
        />
        <p class="rc-option-desc">{{ $t('release_channel_latest_desc') }}</p>
      </div>

      <div class="rc-option">
        <q-radio
          dense
          v-model="selected_channel"
          val="frozen"
          :label="$t('release_channel_frozen_label')"
          data-test="release-channel-option-frozen"
        />
        <p class="rc-option-desc">{{ $t('release_channel_frozen_desc') }}</p>
      </div>
    </div>

    <p class="rc-hint" data-test="release-channel-effect-hint">
      <q-icon name="mdi-information-outline" size="16px" class="q-mr-xs" />
      {{ $t('release_channel_effect_hint') }}
    </p>

    <!-- Save Button -->
    <div class="rc-footer">
      <q-btn
        unelevated
        :label="$t('save')"
        color="primary"
        :disable="!hasChanged"
        @click="save_release_channel"
        size="md"
        data-test="release-channel-save-btn"
      />
    </div>
  </div>
  <Loader />
</template>

<script lang="ts">
import axios from 'axios';
import { notify } from 'src/components/notifications/notify';
import { defineComponent } from 'vue';
import Loader from 'src/components/Loader.vue';
import helperMixin from 'src/mixins/helperMixin.js';
import { ApiExceptions } from 'src/exceptions/index';
import type { dynamicObj } from 'src/pages/assets';
import { DOC2API_URL } from 'src/pages/APIs';
import { setChannel } from 'src/pages/api-base-url';
import { getOrgId } from 'src/utils/organization/org_id_helper';
import releaseChannelApiService, {
  type ReleaseChannel,
} from 'src/services/organization/ReleaseChannelApiService';

export default defineComponent({
  el: '#app',
  mixins: [helperMixin],
  components: {
    Loader,
  },
  data() {
    return {
      selected_channel: 'latest' as ReleaseChannel,
      saved_channel: 'latest' as ReleaseChannel,
      api_version: '' as string,
      api_channel: '' as string,
    };
  },
  computed: {
    hasChanged(): boolean {
      return this.selected_channel !== this.saved_channel;
    },
  },
  mounted() {
    this.load_release_channel();
    this.fetch_api_version();
  },
  methods: {
    async fetch_api_version() {
      // Live proof of the channel router (Multi-Org SD §9.3 B-4): GET the api
      // /health THROUGH the router — on dev, DOC2API_URL IS the channel
      // router (dev-core.api.docbits.com). axiosInterceptor attaches X-ORG-ID
      // for the active org, so the router resolves this org's frozen/latest
      // slot and the returned version is the version this org actually runs
      // on. The X-DocBits-Channel response header states which slot answered.
      // Best-effort: choosing the channel still works if the probe fails.
      try {
        const res = await axios.get(`${DOC2API_URL}/health`, {
          timeout: 8000,
        });
        this.api_version = res?.data?.version || '';
        this.api_channel =
          res?.headers?.['x-docbits-channel'] ||
          res?.headers?.['X-DocBits-Channel'] ||
          '';
      } catch {
        this.api_version = '';
        this.api_channel = '';
      }
    },
    async load_release_channel() {
      try {
        this.showLoading();
        const orgId = getOrgId();
        if (!orgId) {
          return;
        }
        const response =
          await releaseChannelApiService.getReleaseChannel(orgId);
        const channel = (response?.release_channel ||
          'latest') as ReleaseChannel;
        this.selected_channel = channel;
        this.saved_channel = channel;
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
    async save_release_channel() {
      try {
        this.showLoading();
        const orgId = getOrgId();
        if (!orgId) {
          throw new Error('Organisation ID not found');
        }
        await releaseChannelApiService.updateReleaseChannel(
          orgId,
          this.selected_channel,
        );
        this.saved_channel = this.selected_channel;
        notify.success(this.$t('MSG_SAVE'));
        // Host-based routing (DOCB-13416): the channel is baked into the
        // module-load-time service-URL constants (see api-base-url.ts). Just
        // persisting to the backend is NOT enough — the running app keeps the
        // login-time channel's hosts (e.g. still the latest host after
        // switching to frozen) until the next full login. Apply it NOW:
        // setChannel() reloads the page when the channel actually changed, so
        // the whole app (api + docflow + …) immediately re-routes to the new
        // channel's hosts. If the channel is unchanged it does not reload, so
        // refresh the version badge for that case.
        setChannel(this.selected_channel);
        await this.fetch_api_version();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
  },
});
</script>

