import AbstractApiService from 'src/services/abstractApiService';
import { AUTH_URL } from 'src/pages/APIs';

export type ReleaseChannel = 'frozen' | 'latest';

export interface OrganisationReleaseChannelResponse {
  release_channel: ReleaseChannel;
  [key: string]: unknown;
}

/**
 * MO-24 / DOCB-13403 — per-organisation release channel.
 *
 * TODO(DOCB-13404 follow-up): the generated auth SDK
 * (src/generated-auth-sdk/services/OrganisationsService.ts) does not yet
 * expose `PUT /v2/organisations/{org_id}/release-channel` — it's a brand
 * new endpoint added in cloudintegration_subscription PR #1243
 * (feature/DOCB-13402-release-channel). Regenerate the SDK once that PR is
 * merged to dev and switch this service to the generated
 * `OrganisationsService` methods instead of the raw calls below. The GET
 * side already exists in the generated SDK (`getV2Organisations`) but its
 * TS model (`models/Organisation.ts`) is equally stale and doesn't declare
 * `release_channel` yet, so this service calls the raw endpoint for both
 * directions to keep get/update symmetric until the regen lands.
 */
export class ReleaseChannelApiService extends AbstractApiService {
  public constructor() {
    super({});
  }

  // Named getReleaseChannel/updateReleaseChannel (not get/update) - the base
  // AbstractApiService already declares generic get<TRequest, TResponse>() /
  // put<TResponse>() methods with different signatures, so overriding those
  // names here would be an incompatible override (TS2416).
  public async getReleaseChannel(
    orgId: string,
  ): Promise<OrganisationReleaseChannelResponse> {
    // Read via the dedicated org-admin endpoint (DOCB-13403), NOT
    // GET /v2/organisations/{orgId}: that one is gated on the GLOBAL
    // user.is_admin flag, so an org-admin (the audience of this settings
    // card) got a 500 there and the card never rendered. This endpoint
    // mirrors the PUT's org-admin authorization and returns a slim
    // { org_id, release_channel }.
    return this.getWithoutOrgId<OrganisationReleaseChannelResponse>(
      `${AUTH_URL}/v2/organisations/${orgId}/release-channel`,
    );
  }

  public async updateReleaseChannel(
    orgId: string,
    releaseChannel: ReleaseChannel,
  ): Promise<OrganisationReleaseChannelResponse> {
    // AbstractApiService.put() also appends `org_id` to the JSON body (its
    // generic behaviour for every PUT call). The backend schema
    // (OrganisationReleaseChannelUpdateSchema, Meta.unknown = EXCLUDE)
    // silently drops unknown fields, so the extra org_id in the body is
    // harmless — the org_id that actually matters is the one in the URL path.
    return this.put<OrganisationReleaseChannelResponse>(
      `${AUTH_URL}/v2/organisations/${orgId}/release-channel`,
      { release_channel: releaseChannel },
    );
  }
}

export const releaseChannelApiService = new ReleaseChannelApiService();
export default releaseChannelApiService;
